197	\begin{lemma}[Non-encoding support estimate]
198	\label{lem:qld-nonencoding-mass-bound}
199		\lean{MIPStarRE.QPBT.nonencodingMarginalMass_le}
200		\notready
201		For either player and either Pauli basis, the non-encoding marginal mass in
202		Equation~\eqref{eq:qld-nonencoding-mass} is at most the common construction
203		error~$\delta_P$. This bound must be derived from point consistency and
204		Schwartz--Zippel; it is not an additional extraction hypothesis.
205	\end{lemma}
